func (q *Queries) ListDeletedProjects(ctx context.Context) ([]ListDeletedProjectsRow, error) {
	rows, err := q.db.Query(ctx, listDeletedProjects)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListDeletedProjectsRow{}
	for rows.Next() {
		var i ListDeletedProjectsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.Status,
			&i.Sale,
			&i.DeveloperID,
			&i.AreaID,
			&i.Lat,
			&i.Lng,
			&i.Description,
			&i.Media,
			&i.FeaturesAmenities,
			&i.Tags,
			&i.IsFeatured,
			&i.YoutubeUrl,
			&i.GoogleMapsUrl,
			&i.Roi,
			&i.PriceFromUs,
			&i.PriceFromDeveloper,
			&i.PaymentPlan,
			&i.CompletionDate,
			&i.Currency,
			&i.PropertyTypes,
			&i.Bedrooms,
			&i.Bathrooms,
			&i.AreaSize,
			&i.AreaUnit,
			&i.PricesByType,
			&i.TimelineAnnouncement,
			&i.TimelineBookingStarted,
			&i.TimelineConstructionStarted,
			&i.TimelineConstructionProgress,
			&i.TimelineConstructionProgressPct,
			&i.TimelineExpectedCompletion,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.DevName,
			&i.DevLogoUrl,
			&i.AreaName,
			&i.AreaCity,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recalculateProjectPrices = `-- name: RecalculateProjectPrices :exec
UPDATE projects SET
	price_from_us = (SELECT MIN(l.price_from_us) FROM lots l WHERE l.project_id = $1 AND l.deleted_at IS NULL),
	price_from_developer = (SELECT MIN(l.price_from_developer) FROM lots l WHERE l.project_id = $1 AND l.deleted_at IS NULL AND l.price_from_developer IS NOT NULL),
	roi = (SELECT MAX(l.roi) FROM lots l WHERE l.project_id = $1 AND l.deleted_at IS NULL AND l.roi IS NOT NULL),
	prices_by_type = (
		SELECT json_agg(json_build_object('type', label, 'price', min_price) ORDER BY label)
		FROM (
			SELECT
				CASE
					WHEN LOWER(type) = 'apartment' AND bedrooms IS NOT NULL THEN
						type || ' ' || CASE
							WHEN bedrooms = 0 THEN 'studio'
							WHEN bedrooms = 1 THEN '1 bed'
							WHEN bedrooms = 2 THEN '2 beds'
							WHEN bedrooms >= 3 THEN '3+ beds'
							ELSE bedrooms::text || ' beds'
						END
					ELSE type
				END as label,
				MIN(price_from_us) as min_price
			FROM lots
			WHERE project_id = $1 AND deleted_at IS NULL
			GROUP BY 1
		) sub
	),
	property_types = (SELECT COALESCE(ARRAY_AGG(DISTINCT l.type), '{}') FROM lots l WHERE l.project_id = $1 AND l.deleted_at IS NULL AND l.type IS NOT NULL),
	bedrooms = (SELECT COALESCE(ARRAY_AGG(DISTINCT l.bedrooms::text), '{}') FROM lots l WHERE l.project_id = $1 AND l.deleted_at IS NULL AND l.bedrooms IS NOT NULL),
	bathrooms = (SELECT COALESCE(ARRAY_AGG(DISTINCT l.bathrooms::text), '{}') FROM lots l WHERE l.project_id = $1 AND l.deleted_at IS NULL AND l.bathrooms IS NOT NULL),
	updated_at = NOW()
WHERE id = $1 AND deleted_at IS NULL
`

func (q *Queries) RecalculateProjectPrices(ctx context.Context, projectID uuid.NullUUID) error {
	_, err := q.db.Exec(ctx, recalculateProjectPrices, projectID)
	return err
}

const restoreProject = `-- name: RestoreProject :exec
UPDATE projects
SET deleted_at = NULL
WHERE id = $1 AND deleted_at IS NOT NULL
`

func (q *Queries) RestoreProject(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, restoreProject, id)
	return err
}

